-- =============================================
-- 92. 기출 문제 은행 — 문법이 아닌데 영역이 '언어' 로 든 문항 바로잡기 (데이터 교정)
-- 실행: node /Users/ara/Projects/Ara-system/scripts/run-sql.js sql/92_problem_bank_area_fix_non_grammar.sql
-- =============================================
-- sql/91 로 문법 태그를 달다가 나왔다. 영역이 `화법과 언어 > 언어` 인데 문학·화법·작문·독서를 묻는 문항이다. 문법 트리에도 못 들어가고
-- 영역 칸으로 찾아도 엉뚱한 자리에 나온다. 코덱스가 문항을 읽어 영역을 정했다(detach-audit-2026-11-06/tags3/area-fix.json).
--
-- ⚠️ 읽고 정한 값이라 재계산할 수 없다. 지금 영역이 그대로이고 태그가 빈 문항만 고친다(멱등, 그 뒤 손으로 고친 값은 덮지 않는다).
-- ⚠️ 영역만 바꾼다. 지문 연결·작품은 그대로다. 적재 스펙과 판정 기록에도 같은 값을 적었다.

BEGIN;

SET LOCAL search_path = exam, public;

CREATE TEMP TABLE _areas (
  id   UUID PRIMARY KEY,
  area TEXT[] NOT NULL,
  note TEXT NOT NULL
) ON COMMIT DROP;


DO $areas$
DECLARE
  v_total INT;
  v_done  INT;
  v_left  INT;
BEGIN
  IF to_regclass('exam.problems') IS NULL THEN
    RAISE EXCEPTION 'exam.problems 가 없습니다 (현재 DB: %).', current_database();
  END IF;
  SELECT count(*) INTO v_total FROM _areas;

  UPDATE exam.problems p SET area_path = a.area
    FROM _areas a
   WHERE p.id = a.id AND p.area_path = ARRAY['화법과 언어','언어']::text[] AND cardinality(p.grammar_paths) = 0;
  GET DIAGNOSTICS v_done = ROW_COUNT;
  RAISE NOTICE '영역 고침 % / 건너뜀 % (목록 %)', v_done, v_total - v_done, v_total;

  SELECT count(*) INTO v_left FROM exam.problems
   WHERE area_path[1] = '화법과 언어' AND area_path[2] = '언어' AND cardinality(grammar_paths) = 0;
  RAISE NOTICE '문법 영역의 빈 태그 %', v_left;
END
$areas$;

SELECT exam.archive_facets_refresh();

COMMIT;
